export const KYP_LOOKUP: KypLookupEntry[] = [{"category":"Plansifter Accessories","item":"Milling Fabric","aliases":["nylon mesh","filtration cloth","Swiss jolly","Resham ki jali","reshmi jaali","bolting cloth","Nytal bolting cloth","sieve cloth","sieving gauze","sifting cloth","gauze cloth"],"required_attributes":["Ask grade and the number within the grade -- 4 grade families exist: GG (6 GG to 74 GG), XXX (3 XXX to 17 XXX), MF (3 MF to 13 MF), N / double-X (3 N to 25 N)","Ask fabric family: standard sieving fabric, Milling Forte (heavier thread, same opening, longer life), or heavy-duty XXX grade -- trade-off is service life vs open (sifting) area","Ask width: 3 standard widths stocked -- 115 cm, 136 cm, 158 cm","Ask length in meters -- priced and ordered per meter","Ask the plansifter make -- frame/stretching sizes differ by machine (1250x1250 mm and 1500x1500 mm are common)","Ask the micron opening if the client knows it; if not, ask what flour it is sifting (maida, suji/rava, chokar/bran) so the opening can be matched to the product, since spec is really driven by micron opening rather than the grade number alone","If the client is unsure of the grade, request a picture or a physical swatch of the old cloth"]},{"category":"Plansifter Accessories","item":"Plansifter Sleeves","aliases":["plansifter socks","inlet and outlet sleeves","plansifter small and big bag","connector sleeves","spout sleeves","bellows sleeve"],"required_attributes":["Ask diameter and length in inches, being clear whether it is flat diameter or actual (inflated) diameter -- these two numbers are different and easy to mix up","Ask finishing option: single ring in the center, or elastic on both top and bottom","Ask fabric option: Indian regular, Turkish, or imported (most expensive)","Ask the plansifter make/model as an alternative to exact dimensions -- sizes are frame-specific and vary a lot between machines","Ask quantity of bags/pieces required","If the client has a specific fabric or the exact old sleeve, request a picture or a sample -- easy to send the wrong size without one"]},{"category":"Plansifter Accessories","item":"Manual Gun Tacker","aliases":["staple gun","hand tacker","manual stapler gun","tacker gun"],"required_attributes":["Ask quantity and any brand preference -- Kangaroo and Max are the common manual brands stocked","If unsure, offer a reference picture"]},{"category":"Plansifter Accessories","item":"Pneumatic Tacker","aliases":["air tacker","pneumatic staple gun","air stapler"],"required_attributes":["Ask the working air pressure / compressor capacity available at the client's site","Ask the pin/staple size the tool should take (see Staple Pin)","Ask brand preference and quantity","If unsure, offer a reference picture"]},{"category":"Plansifter Accessories","item":"Felt Seal","aliases":["namda tape","felt tape","Nivard tape","gasket felt"],"required_attributes":["Ask which type: Namda tape, cotton tape (Nivard), or glue-backed (peel-paper) tape -- construction and MOQ differ by type","Namda tape: ask width and thickness; MOQ 100 m per roll","Nivard (cotton) tape: thickness is fixed at 1 mm, so only ask width; MOQ 50 m per roll","Glue-type tape: only available in 3 mm thickness; ask width and quantity; MOQ 100 m per roll","Always confirm quantity in meters"]},{"category":"Plansifter Accessories","item":"Fiber Rod / Nylon Rod","aliases":["plansifter fiber","nylon rod","fibre rod"],"required_attributes":["Ask diameter/thickness, length, and quantity","Request a picture to confirm the material -- fiber and nylon look near-identical and clients are often unsure which they actually have"]},{"category":"Plansifter Accessories","item":"Plansifter Wooden Frame","aliases":["sieve frame","plansifter frame","chalni frame"],"required_attributes":["Ask the make of the plansifter -- frame size is machine-specific","Ask finish: plain wooden, or with Sunmica laminate (increases service life)","Ask what sits underneath the mesh: round-hole perforated sheet (6 mm holes) or double crimped mesh, and for the perforated option ask gauge -- 28 gauge (better quality) or 32 gauge (cheaper, thinner)","Ask quantity, priced per piece","If unsure, offer/request a picture"]},{"category":"Plansifter Accessories","item":"Stainless Steel Wire Mesh","aliases":["SS wire mesh","SS jaali","stainless sieve mesh","woven wire cloth"],"required_attributes":["Ask mesh count (holes per inch); if the client does not know it, ask the opening in microns or mm (mm = wire-to-wire distance)","Ask wire thickness in mm or gauge","Ask width -- standard is 4 ft (3 ft, 5 ft, 2 m, or wider also available)","Ask length required; quantity is priced per meter","Ask grade: 304 (standard, corrosion-resistant) or 202 (cheaper, lower corrosion resistance)"]},{"category":"Plansifter Accessories","item":"Staple Pin","aliases":["tacker pin","staples","gun tacker pin"],"required_attributes":["Ask leg length and crown width (mm) -- must match the tacker brand/model, since pins for one gun brand do not always fit another; confirm which tacker/brand the client owns before quoting","Ask material: galvanized or stainless","Ask number of boxes required -- 1 box = 20 packets, and it is priced/sold per box"]},{"category":"Plansifter Accessories","item":"Plansifter Wire Rope","aliases":["suspension rope","hanging wire rope","sifter suspension cable"],"required_attributes":["Ask what it is for -- plansifter suspension/hanging vs general lifting/hoisting -- since the spec needed differs by use","Ask thickness/diameter of the wire rope (mm)","Ask length/quantity required","Ask material/construction: mild steel (galvanized) or stainless steel, and specific grade if the client has a preference","If unsure of the exact rope needed, offer a reference picture"]},{"category":"Plansifter Accessories","item":"Paper Gum Tape","aliases":["water-activated tape","gummed paper tape","kraft tape"],"required_attributes":["Ask width: 1 inch, 1.5 inch, or 2 inch","Ask number of bales -- 1 inch = 30 rolls x 25 m per bale; 1.5 inch = 20 rolls x 25 m per bale; 2 inch = 15 rolls x 25 m per bale"]},{"category":"Plansifter Accessories","item":"Plansifter Upper & Lower Housing","aliases":["plansifter casing","sifter body","upper and lower body"],"required_attributes":["Ask the manufacturer name of the plansifter","Ask the size of the plansifter","Ask quantity in pieces","Request pictures to confirm the exact part -- this is a large, made-to-order part, not stocked"]},{"category":"Plansifter Accessories","item":"Plansifter Step Sheet","aliases":["step plate","plansifter step plate"],"required_attributes":["Ask variant: with hole or without hole","Ask material: MS (regular iron), or stainless steel if requested","Ask quantity"]},{"category":"Plansifter Accessories","item":"Plansifter Tin Sheet","aliases":["tensheet","plansifter tin plate"],"required_attributes":["Ask material: mild steel (standard) or stainless steel if requested","Ask gauge: 28 gauge or 32 gauge","Ask quantity"]},{"category":"Plansifter Accessories","item":"Double Crimped Mesh","aliases":["crimped wire mesh","woven crimp mesh"],"required_attributes":["Ask opening size: 8 mm, 10 mm, or 12 mm","Ask quantity"]},{"category":"Plansifter Accessories","item":"Plansifter Channel","aliases":["sifter channel bracket"],"required_attributes":["Ask brand of the plansifter","Ask size of the channel","Ask quantity","Request a picture to confirm"]},{"category":"Plansifter Accessories","item":"Brass Brush","aliases":["mesh cleaning brush"],"required_attributes":["Ask quantity in pieces -- one size only, no size question needed"]},{"category":"Plansifter Accessories","item":"Plansifter Works (Box)","aliases":["sifter box assembly","plansifter compartment box"],"required_attributes":["Ask brand of the plansifter","Ask size of the plansifter","Ask section of the box (E section or other)","Ask quantity of boxes"]},{"category":"Plansifter Accessories","item":"Oval Ball","aliases":["dolag ball","dumbru ball","sieve cleaning ball"],"required_attributes":["Ask the plansifter make -- three standard sizes/numbers (Type 1/2/3) exist and fit differs by machine; ask which type, or the diameter in mm, if the client is unsure","Ask material: rubber, nylon (= plastic), or PVC (clear, also called penny ball); PVC is also available in a food-grade variant","Ask material/hardness of the rubber if known","Ask quantity -- MOQ differs by material: rubber 500 pcs, nylon 200 pcs, PVC 200 pcs; order strictly in multiples of the MOQ","Offer a reference picture -- the three types look alike at a glance"]},{"category":"Plansifter Accessories","item":"Rectangular Sieve Cleaner","aliases":["PU rectangular cleaner"],"required_attributes":["Ask knob type: metal or plastic in the center","Ask quantity"]},{"category":"Plansifter Accessories","item":"Triangle Cleaner (Standard)","aliases":["triangle sieve cleaner"],"required_attributes":["Ask which trim combination the client currently has fitted: with brush, with studs, with metal knob, or with plastic knob","If the brush variant, ask quality: polyurethane, PU, or PU with a full internal nylon brush hidden inside (most expensive)","Ask size (length x width, mm) and quantity -- ordered in multiples of 100","Request a picture or the old part -- this design has the most variants in the range"]},{"category":"Plansifter Accessories","item":"Big Triangle Cleaner","aliases":["large triangle cleaner"],"required_attributes":["Confirm it is genuinely the 'big' size vs the standard triangle cleaner","Ask trim: with brush or with studs, and brush type if applicable","Ask size and quantity","Offer a reference picture if unsure"]},{"category":"Plansifter Accessories","item":"Star Type Cleaner","aliases":["star sieve cleaner"],"required_attributes":["Ask trim: with brush or with studs","Ask size and quantity"]},{"category":"Plansifter Accessories","item":"Rubber Ball","aliases":["plain rubber ball"],"required_attributes":["Ask diameter (mm) -- 16 mm is the standard/default size -- and hardness if known","Ask bounce type: high bounce or medium bounce","Ask quantity -- MOQ 500 pcs, order in multiples of 500"]},{"category":"Plansifter Accessories","item":"Cotton Cleaner","aliases":["cotton sieve pad","cotton cleaner pad"],"required_attributes":["Ask ply/grade: 2 ply (Indian manufacture), 4 ply (imported, sturdier), 6 ply light green (70% cotton / 30% polyester), or 6 ply dark green (100% cotton, best quality)","Ask quantity","Offer a reference picture if unsure -- a common market size is roughly 75x58x8 mm sold about 500 pieces to a carton, but confirm the exact size and pack count before quoting"]},{"category":"Plansifter Accessories","item":"Blue Cleaner with Brush, Studs","aliases":["blue cleaner"],"required_attributes":["Confirm size -- many clients order this by colour name alone ('Blue Cleaner'), so size still needs confirming","Ask quantity","Offer a reference picture if unsure"]},{"category":"Conveying Accessories","item":"Elevator Bucket - AA Type","aliases":["AA-style bucket","double A bucket","elevator cups","grain elevator buckets"],"required_attributes":["Ask size (width x projection x depth, usually in inches)","Ask material: mild steel, stainless steel, PP, or Nylon -- MS/SS ask gauge too (18, 16, 14, 12, or 10 gauge)","Ask the elevator make/model and mounting hole pattern if known","Ask quantity","If unsure of size, offer a reference picture"]},{"category":"Conveying Accessories","item":"Elevator Bucket - Shovel Type","aliases":["shovel bucket","deep scoop bucket"],"required_attributes":["Ask size and material: MS, SS, PP, or Nylon -- MS/SS ask gauge too (18, 16, 14, 12, or 10 gauge)","Ask the elevator make/model","Ask quantity","If unsure, offer a reference picture"]},{"category":"Conveying Accessories","item":"Black Rubber Belt","aliases":["rubber conveyor belt","black belting"],"required_attributes":["Ask width required","Ask plies/thickness: 3 ply (8 mm), 4 ply (10 mm), or 5 ply (12 mm)","Ask top/bottom rubber cover thickness","Ask length required, and whether it should be supplied open-ended or as an endless (spliced) loop","Ask quantity (in meters)"]},{"category":"Conveying Accessories","item":"Food Grade Belt","aliases":["white rubber belt","hygienic belt","FDA-grade belt","FSSAI belt"],"required_attributes":["Ask width required","Ask plies/thickness: 3 ply (8 mm), 4 ply (10 mm), or 5 ply (12 mm)","Confirm food-grade certification needed (FDA / FSSAI) -- this is what distinguishes it from a standard black rubber belt","Ask top and bottom cover type/colour","Ask length required (ordered by the meter) and quantity"]},{"category":"Conveying Accessories","item":"Cotton, Nylon, Polyester Belt","aliases":["fabric conveyor belt","nylon-cotton belting"],"required_attributes":["Ask which material the client wants: cotton, nylon-cotton, or polyester -- thickness is fixed at 8 mm for all three","Ask width, ply count, and length","Ask quantity"]},{"category":"Conveying Accessories","item":"PVC / PU Conveyor Belt","aliases":["polyurethane belt","PVC belting","PU belting","plastic conveyor belt"],"required_attributes":["Ask material: PVC or PU (polyurethane)","Ask thickness: 1 mm, 2 mm, 3 mm, or up to 5 mm","Ask width and length required","Ask quantity"]},{"category":"Conveying Accessories","item":"Yellow Nylon Belt","aliases":["yellow belting"],"required_attributes":["Ask thickness","Ask width and length required","Ask quantity"]},{"category":"Conveying Accessories","item":"Sandwich Belt","aliases":["two-tone conveyor belt","dual colour belt"],"required_attributes":["Ask thickness","Ask top-surface and bottom-surface colours/materials -- top and bottom differ by design","Ask width and length required","Ask quantity"]},{"category":"Conveying Accessories","item":"Hair Belt","aliases":["camel hair belt","camel hair belting","woven cotton transmission belt"],"required_attributes":["Ask the application first to settle which product is actually meant -- the term gets used locally for two different things: a napped/rough-surface belt for extra grip on inclined conveying, or a woven cotton/'camel hair' flat transmission belt used to drive a machine","If conveying: ask width, thickness (8 mm or 10 mm), and length","If machine drive: ask width, thickness, and length to suit the pulleys","Ask quantity"]},{"category":"Conveying Accessories","item":"Transmission Belt","aliases":["drive belt","machine drive belt"],"required_attributes":["Ask type: flat belt or V-belt","If V-belt: ask section (A/B/C/Z or SPA/SPB/SPZ) and length/belt number","If flat belt: ask width and thickness","Ask quantity"]},{"category":"Conveying Accessories","item":"Bucket Bolt","aliases":["elevator bolt","oval neck bolt","carriage-type bucket bolt"],"required_attributes":["Ask diameter: 6 mm, 8 mm, or 10 mm are the three standard sizes (12 mm is a non-standard size also available); clients may refer to these in inches -- 8 mm = 5/16 inch, 10 mm = 3/8 inch","Ask length: 6 mm dia = 1 inch; 8 mm dia = 1 inch or 1.25 inch; 10 mm dia = 1.5 inch","Ask head type: oval, countersunk, or round","Ask material: GI or stainless steel","Confirm whether nuts and washers are needed with it","Ask quantity -- MOQ is 100 pieces per pack for 6 mm and 8 mm, 50 pieces per pack for 10 mm"]},{"category":"Conveying Accessories","item":"Nylock Nut","aliases":["nyloc nut","nylon insert lock nut","self-locking nut"],"required_attributes":["Ask size: 8 mm or 10 mm (to match the Bucket Bolt diameter)","Ask quantity -- sold per piece, any quantity accepted"]},{"category":"Conveying Accessories","item":"Belt Fastener","aliases":["belt lacing","hinged plate fastener","belt clipper"],"required_attributes":["Ask fastener type: hinged plate, wire-hook, or staple/clipper type","Ask size: 8 mm or 10 mm (8 mm packs = 50 pieces, MOQ 50)","Ask belt width (mm) and belt thickness/ply to match","Ask quantity -- usually sold per set/box covering one joint width","If unsure which type is needed, offer a reference picture"]},{"category":"Conveying Accessories","item":"Special Conveyor Belt Fasteners","aliases":["clipper lacing","wire hook fastener"],"required_attributes":["Ask fastener size/number: 1.5 number, 2 number, 2.5 number, or 3 number","Ask belt width and thickness/ply to match","Ask quantity"]},{"category":"Roller Mill Accessories","item":"Roller Mill Brush","aliases":["roll cleaning brush","mill hand brush"],"required_attributes":["Ask hair/bristle type: nylon brush, peacock feather brush, or jute brush (also called coconut brush)","Ask width of the brush: 2 inch (standard) or 1 inch (non-standard)","Ask thickness of the wood: generally 20 mm, or as specified by the client","Ask length of the wood: 40 inch or 50 inch standard (can also be specified in mm: 1000 mm or 1250 mm)","Ask hair height: generally 1.5 inch; custom heights of 2 inch, 2.5 inch, or other available","Ask quantity"]},{"category":"Roller Mill Accessories","item":"Roller Mill Helical Gear","aliases":["differential gear","roll drive gear","speed differential gear set"],"required_attributes":["Ask which passage the gear is for: break passage or polish passage -- gearing differs by passage since break and polish rolls run at different differential ratios","If the client is specifying a single gear: ask number of teeth, bore size (hole in center -- generally 60 mm, or custom e.g. 70 mm), and quantity required","If the client needs a matched pair (proper gear set): ask the center distance between the big and small gear (measured by joining them and measuring hole-to-hole), the bore size, and number of pairs required","Request a picture or the old gear's marking if unsure","Ask the roller mill make/model -- gears are usually matched in pairs to keep the correct differential speed ratio between the fast and slow roll"]},{"category":"Roller Mill Accessories","item":"Roller Mill Viewing Glass","aliases":["sight glass","inspection glass","roller mill window"],"required_attributes":["Ask diameter, length, and thickness","Ask variant: with partition or without partition","Ask whether a frame/gasket is needed with it","Ask the roller mill make/model","Ask quantity required"]},{"category":"Roller Mill Accessories","item":"Chilled Cast Iron Rolls","aliases":["CI rolls","chill rolls","chilled rolls","fluted rolls","corrugated rolls","break rolls","reduction rolls","smooth rolls"],"required_attributes":["Ask diameter and length -- standard sizes are 250 mm dia in 1000 mm or 1250 mm length; a 300 mm dia is also available (non-standard) in 1000 mm or 1250 mm length","Ask passage type: break passage (fluted/corrugated roll) or polish/reduction passage (usually smooth roll)","If fluted, ask fluting spec: flutes per inch (FPI/TPI), and spiral angle if the client knows it -- flute count and angle are what actually set the grind, not just diameter","Ask manufacturing preference: Indian-manufactured or imported (Turkey)","Ask number of pairs required (rolls are always ordered and fitted as a matched fast/slow pair)"]},{"category":"Roller Mill Accessories","item":"Roller Mill Spring","aliases":["roll pressure spring","compression spring"],"required_attributes":["Ask outer diameter","Ask inner diameter","Ask thickness (wire gauge) of the spring","Ask length/height of the spring","Ask number of coils/loops","Ask quantity required","Prefer that the client provide a reference picture"]},{"category":"Roller Mill Accessories","item":"Roller Mill Housing","aliases":["roll bearing housing","chock"],"required_attributes":["Ask brand of the roller mill","Ask bearing number used inside the housing","Ask quantity required"]},{"category":"Roller Mill Accessories","item":"Roller Mill Key","aliases":["taper key","gear key"],"required_attributes":["Ask quantity required","Prefer that the client provide a reference picture"]},{"category":"Roller Mill Accessories","item":"Roll Cleaning Brush Type 1, 2, 3","aliases":["roll scraper brush","feed roll brush"],"required_attributes":["Ask which type/number, or the roll length (mm), if the client is unsure which of the 3 types is needed","Ask bristle material: nylon or steel wire","Ask the roller mill make/model","Ask quantity","Offer a reference picture if unsure which type"]},{"category":"Roller Mill Accessories","item":"Roller Mill Flat & V Belt Pulley","aliases":["roll drive pulley"],"required_attributes":["Ask whether a flat or V-groove pulley is needed","If V-groove: ask number of grooves and section (A/B/C)","Ask pulley diameter and bore/shaft size","Ask the roller mill make and quantity"]},{"category":"Roller Mill Accessories","item":"Doctor Blade (Roll Scraper)","aliases":["scraper blade","doctor knife"],"required_attributes":["Ask blade length to match the roll's working length, and material (spring steel is standard)","Ask the roller mill make/model and which roll (fast or slow) it mounts against","Ask quantity"]},{"category":"Power Transmission Elements","item":"Oil Seal","aliases":["rotary shaft seal","lip seal","grease seal","oil seal ring"],"required_attributes":["Ask inner diameter (ID) x outer diameter (OD) x thickness, all three in mm -- all three are needed for an exact match","Ask lip type: single or double lip, with or without spring","Ask rubber type: neoprene, silicon, or regular black (default if not specified)","Ask quantity required"]},{"category":"Power Transmission Elements","item":"V Belt","aliases":["wedge belt","vee belt","V-patti"],"required_attributes":["Ask V-belt number (every V-belt has a number, e.g. A70, B110) or section (A/B/C/Z or SPA/SPB/SPZ) plus length/belt number","Ask brand preference -- client may specify one or two preferred brands","Ask quantity required"]},{"category":"Power Transmission Elements","item":"Bearing Sleeve","aliases":["adapter sleeve","withdrawal sleeve"],"required_attributes":["Ask the sleeve number if stamped on it (e.g. H2310), else the shaft diameter it must fit","Ask series if known: H series (bore in mm) or HE series (bore in inches)","Ask brand preference -- many brands available, JMC is the most common","Ask quantity required"]},{"category":"Power Transmission Elements","item":"Bearing Block","aliases":["pillow block bearing","plummer block","bearing housing unit"],"required_attributes":["Ask the bearing block number if known: S series or SN series","Ask housing type/series if known (e.g. P or F series), or ask for a picture of the housing","Ask shaft/bore diameter","Ask material: cast iron or pressed steel","Ask brand preference -- JMC is most common; ask if the client requires a different brand","Ask quantity required"]},{"category":"Power Transmission Elements","item":"Gear Box","aliases":["speed reducer","reducer gearbox","worm reducer"],"required_attributes":["Ask which way the client will specify it -- by HP + output RPM, or by frame size (inches) + ratio -- and gather accordingly:","If by HP/RPM: ask HP (e.g. 2 HP) and output RPM (e.g. 50)","If by inches/ratio: ask the gearbox size in inches (e.g. 2 inch) and the ratio (e.g. 1:10 or 1:20)","Ask mounting type: foot-mounted or flange-mounted","Ask brand preference","Ask quantity required"]},{"category":"Power Transmission Elements","item":"Motor","aliases":["electric motor","induction motor"],"required_attributes":["Ask HP of the motor","Ask RPM of the motor (e.g. 1 HP at 1,440 rpm)","Ask brand preference","Ask quantity required"]},{"category":"Power Transmission Elements","item":"Gear Box and Motor","aliases":["gearmotor","geared motor"],"required_attributes":["Ask gearbox type: worm or helical","Ask reduction ratio, input/output shaft size, and mounting (foot or flange)","Ask motor power (HP/kW), RPM, and voltage/phase","Ask quantity"]},{"category":"Power Transmission Elements","item":"HRC Coupling","aliases":["Highly Resilient Coupling","rubber spider coupling","jaw coupling"],"required_attributes":["Ask HRC size number if known (e.g. HRC 90, 100, 110, 130), else both shaft bore diameters","Ask quantity required"]},{"category":"Power Transmission Elements","item":"Pin Bush Coupling","aliases":["pin and bush coupling","flexible pin bush coupling"],"required_attributes":["Ask coupling number if known (BC series: BC1, BC2, BC2A, and so on), else the overall coupling diameter","Ask size number if known, else both shaft bore diameters","Ask quantity required"]},{"category":"Power Transmission Elements","item":"Tyre Coupling","aliases":["tire coupling","rubber tyre coupling"],"required_attributes":["Ask tyre coupling number if known -- two series exist, FC series and T series","Ask size number if known, else both shaft bore diameters","Ask quantity required"]},{"category":"Power Transmission Elements","item":"Muff Coupling","aliases":["sleeve coupling","solid sleeve coupling"],"required_attributes":["Ask both shaft diameters and the bore the client wants","Ask the total length/OD of the muff","Ask quantity required"]},{"category":"Power Transmission Elements","item":"Chain Coupling","aliases":["roller chain coupling"],"required_attributes":["Ask both shaft bore diameters","Ask coupling size: number of teeth, pitch, or the chain pitch/number it uses","Ask quantity required","Send the old coupling's size marking or a picture if unsure"]},{"category":"Power Transmission Elements","item":"Encoder Coupling","aliases":["beam coupling","servo coupling","flexible shaft coupling"],"required_attributes":["Ask outer diameter","Ask inner diameter (both shaft ends)","Ask length","Ask quantity required"]},{"category":"Power Transmission Elements","item":"Gear Coupling","aliases":["toothed coupling"],"required_attributes":["Ask gear coupling number if known, else both shaft bore diameters","Ask quantity required"]},{"category":"Power Transmission Elements","item":"Star Coupling","aliases":["jaw coupling (Lovejoy-type)","L-type coupling"],"required_attributes":["Ask coupling number (e.g. L100, L110) if known, else bore size (e.g. 30 mm, 40 mm) and confirm both shaft bore diameters","Ask whether just the rubber spider/star element is needed, or the full coupling (both hubs)","Ask quantity required"]},{"category":"Power Transmission Elements","item":"Simplex Chain Sprocket","aliases":["single row sprocket"],"required_attributes":["Ask number of teeth","Ask bore size: finished bore + keyway, or 'pilot bore' if it is to be machined later; optionally also overall diameter and hub diameter","Ask the chain pitch/number it must match, e.g. 08B, 10B, or ANSI 40/50/60 (standard pitches: 1/2 in, 3/8 in, 5/8 in, 1 in)","Ask hub type if known","Ask quantity required"]},{"category":"Power Transmission Elements","item":"Simplex Chain","aliases":["single row roller chain"],"required_attributes":["Ask chain pitch/number, e.g. 08B, 10B, ANSI 40/50/60, or 1/2 in - 3/4 in - 1 in pitch","Ask length required -- in number of links, meters, or 'same as sample'; note it is sold in packets, 1 packet = 3 m (about 10 ft)","Ask number of packets required"]},{"category":"Power Transmission Elements","item":"Duplex Chain Sprocket","aliases":["double row sprocket"],"required_attributes":["Confirm duplex (double-row) is what is needed, then ask the same as simplex: number of teeth, bore, chain pitch/number, hub type","Ask quantity"]},{"category":"Power Transmission Elements","item":"Duplex Chain","aliases":["double row roller chain"],"required_attributes":["Confirm duplex (double-row) vs simplex before quoting","Ask chain pitch/number, length required, and quantity"]},{"category":"Power Transmission Elements","item":"Triplex Chain Sprocket","aliases":["triple row sprocket"],"required_attributes":["Confirm triplex (triple-row) is what is needed, then ask the same as simplex/duplex: number of teeth, bore, chain pitch/number, hub type","Ask quantity"]},{"category":"Power Transmission Elements","item":"Triplex Chain","aliases":["triple row roller chain"],"required_attributes":["Confirm triplex (triple-row)","Ask chain pitch/number, length required, and quantity"]},{"category":"Power Transmission Elements","item":"Angular Contact Ball Bearing","aliases":["ACBB"],"required_attributes":["Ask the bearing number if visible, else bore diameter, outer diameter, and width (mm)","Ask contact angle if known (commonly 15deg/25deg/40deg) and single or double row","Ask brand preference and quantity"]},{"category":"Power Transmission Elements","item":"Cylindrical Roller Bearing","aliases":["CRB"],"required_attributes":["Ask the bearing number if visible, else bore, outer diameter, width","Ask configuration if known (N, NU, NJ, NUP -- affects which side takes axial load)","Ask brand preference and quantity"]},{"category":"Power Transmission Elements","item":"Deep Groove Bearing","aliases":["deep groove ball bearing","DGBB","Conrad bearing","ball bearing"],"required_attributes":["Ask the bearing number if visible, else bore, outer diameter, width","Ask if sealed/shielded (2RS/ZZ) or open is needed","Ask brand preference and quantity"]},{"category":"Power Transmission Elements","item":"Needle Bearing","aliases":["needle roller bearing"],"required_attributes":["Ask the bearing number if visible, else bore diameter, outer diameter, and width","Ask whether it is a needle roller with inner ring, without inner ring, or a needle bush/cage","Ask brand preference and quantity"]},{"category":"Power Transmission Elements","item":"Self Aligning Ball Bearing","aliases":["SABB"],"required_attributes":["Ask the bearing number if visible, else bore, outer diameter, width","Confirm the application needs misalignment tolerance (this type's key feature), so it is not substituted for a standard deep groove bearing by mistake","Ask brand preference and quantity"]},{"category":"Power Transmission Elements","item":"Spherical Roller Bearing","aliases":["SRB","barrel roller bearing"],"required_attributes":["Ask the bearing number if visible, else bore, outer diameter, width","Ask whether it needs a tapered bore (for adapter-sleeve mounting) or a straight bore","Ask brand preference and quantity"]},{"category":"Power Transmission Elements","item":"Taper Roller Bearing","aliases":["TRB","Timken bearing","tapered roller bearing"],"required_attributes":["Ask the bearing number if visible, else bore, outer diameter, width, and cone angle if known","Confirm single or double row","Ask brand preference and quantity"]},{"category":"Power Transmission Elements","item":"Thrust Ball Bearing","aliases":[],"required_attributes":["Ask the bearing number if visible, else bore, outer diameter, and height","Confirm it is genuinely for axial load only (thrust bearings do not take radial load) -- worth double-checking this is what the machine needs","Ask brand preference and quantity"]},{"category":"Power Transmission Elements","item":"Flat Belt Pulley","aliases":[],"required_attributes":["Ask diameter, face width, and bore/shaft size","Ask quantity"]},{"category":"Power Transmission Elements","item":"Plain Bore V Belt Pulley","aliases":["fixed bore V-pulley"],"required_attributes":["Ask pitch diameter, number of grooves, section (A/B/C), and bore diameter","Ask quantity"]},{"category":"Power Transmission Elements","item":"Taper Bush V Belt Pulley","aliases":["taper lock pulley"],"required_attributes":["Ask pitch diameter, number of grooves, and section","Ask the taper bush size/number if known, and the finished bore needed in the bush","Ask quantity"]},{"category":"Power Transmission Elements","item":"Timing Pulley","aliases":["toothed pulley","synchronous pulley"],"required_attributes":["Ask tooth profile/pitch (e.g. T5, T10, AT5, HTD 8M), number of teeth, belt width, and bore size","Request a picture or the belt sample if unsure of the tooth profile -- profiles look similar but are not interchangeable","Ask quantity"]},{"category":"Power Transmission Elements","item":"Circlip (Retaining Ring)","aliases":["snap ring","retaining ring","C-clip"],"required_attributes":["Ask shaft (external) or bore (internal) type","Ask diameter to match the shaft/bore, and thickness","Ask material: spring steel (standard) or stainless","Ask quantity"]},{"category":"Power Transmission Elements","item":"Grease Nipple","aliases":["zerk fitting","grease fitting","lubrication nipple"],"required_attributes":["Ask thread size and type (metric or BSP) and angle (straight, 45deg, or 90deg)","Ask quantity"]},{"category":"Pipe & Pipe Accessories","item":"Divider","aliases":["flow divider","diverter valve","multi-way divider"],"required_attributes":["Ask pipe diameter and number of outlets","Ask whether a manual or pneumatic damper/flap is needed to select the outlet","Ask material: GI, MS, or SS","Ask quantity"]},{"category":"Pipe & Pipe Accessories","item":"Down Gravity Pipe","aliases":["gravity chute","down spout"],"required_attributes":["Ask diameter, length, and number of bends","Ask material and quantity"]},{"category":"Pipe & Pipe Accessories","item":"Elbow Bend","aliases":["elbow","pipe bend"],"required_attributes":["Ask diameter, angle (45deg or 90deg), and material","Ask quantity"]},{"category":"Pipe & Pipe Accessories","item":"Lock Ring","aliases":["pipe clamp ring","band clamp"],"required_attributes":["Ask diameter to match the pipe it clamps, and material","Ask quantity"]},{"category":"Pipe & Pipe Accessories","item":"Spout Cover","aliases":["spout cap"],"required_attributes":["Ask diameter and material","Ask quantity"]},{"category":"Pipe & Pipe Accessories","item":"Tee","aliases":["T-piece","T-joint"],"required_attributes":["Ask diameter, whether equal or reducing, and material","Ask quantity"]},{"category":"Pipe & Pipe Accessories","item":"U Bolt","aliases":[],"required_attributes":["Ask the pipe/rod diameter it needs to clamp, and material","Ask quantity"]},{"category":"Pipe & Pipe Accessories","item":"U Clamp","aliases":["saddle clamp"],"required_attributes":["Ask diameter and width, and material","Ask quantity"]},{"category":"Pipe & Pipe Accessories","item":"Y (Y-Piece)","aliases":["wye fitting","Y-branch"],"required_attributes":["Ask diameter, branch angle, and material","Ask quantity"]},{"category":"Pipe & Pipe Accessories","item":"Reducer","aliases":["pipe reducer","concentric/eccentric reducer"],"required_attributes":["Ask both diameters (larger end and smaller end)","Ask concentric (centered) or eccentric (offset) type, and material","Ask quantity"]},{"category":"Jet Filter Accessories","item":"Filter Diaphragm","aliases":["valve diaphragm","pulse valve diaphragm"],"required_attributes":["Ask the valve brand/model it is for, and diaphragm size","Ask quantity"]},{"category":"Jet Filter Accessories","item":"Jet Filter Bag","aliases":["filter sock","dust collector bag","pulse jet bag"],"required_attributes":["Ask bag diameter x length (mm)","Ask fabric: polyester, PTFE, or Nomex, and micron rating if known","Ask top/bottom fitting type: snap ring or flange","Ask quantity"]},{"category":"Jet Filter Accessories","item":"Jet Filter Cage","aliases":["bag cage","filter basket"],"required_attributes":["Ask cage diameter x length, and material (GI or SS) -- must match the Jet Filter Bag size","Ask quantity"]},{"category":"Jet Filter Accessories","item":"Jet Filter Venturi","aliases":["venturi nozzle"],"required_attributes":["Ask throat/venturi size to match the bag diameter, and material","Ask quantity"]},{"category":"Jet Filter Accessories","item":"Sequential Timer","aliases":["pulse jet timer","pulse controller"],"required_attributes":["Ask number of outputs/channels needed","Ask voltage (220V AC or 24V DC) and brand preference","Ask quantity"]},{"category":"Jet Filter Accessories","item":"Solenoid Valve","aliases":["pulse valve"],"required_attributes":["Ask valve size in inches (e.g. 1 in, 1.5 in, 2 in)","Ask voltage (220V AC or 24V DC) and brand preference","Ask quantity"]},{"category":"Magnets","item":"Drawer Magnet","aliases":["magnetic drawer separator","grid magnet drawer"],"required_attributes":["Ask duct size (width x height)","Ask number of magnetic rods/tubes and gauss rating","Ask quantity"]},{"category":"Magnets","item":"Grill Magnet","aliases":["magnetic grill","grid magnet"],"required_attributes":["Ask duct/opening size and number of magnetic rods","Ask gauss rating and quantity"]},{"category":"Magnets","item":"Hump Magnet","aliases":["magnetic hump","chute magnet"],"required_attributes":["Ask duct size and gauss rating","Ask quantity"]},{"category":"Magnets","item":"Magnetic De-Stoner","aliases":["magnetic gravity separator"],"required_attributes":["Ask capacity (tonnes/hour) and duct size","Ask the machine make it is a spare for, if applicable","Ask quantity"]},{"category":"Magnets","item":"Online Magnet","aliases":["in-line magnet","pipeline magnet"],"required_attributes":["Ask pipe/duct diameter and gauss rating","Ask quantity"]},{"category":"Magnets","item":"Plate Magnetic Separator","aliases":["plate magnet","magnetic plate"],"required_attributes":["Ask plate size (length x width) and thickness","Ask gauss rating","Ask quantity"]},{"category":"Magnets","item":"Rotary Magnet","aliases":["drum magnet","magnetic drum separator"],"required_attributes":["Ask drum diameter, duct size, and gauss rating","Confirm if a drive/motor is needed with it","Ask quantity"]},{"category":"Magnets","item":"Self Cleaning Magnet","aliases":["self-cleaning magnetic separator"],"required_attributes":["Ask duct size and gauss rating","Confirm the cleaning mechanism wanted: manual pull-out vs self-rotating","Ask quantity"]},{"category":"Magnets","item":"Three Stage Magnet","aliases":["multi-stage magnetic separator","cascade magnet"],"required_attributes":["Ask duct size","Ask number of magnetic rods per stage and gauss rating per stage","Ask quantity"]},{"category":"Wire Mesh","item":"De-Stoner Mesh","aliases":["destoner deck mesh","gravity separator mesh"],"required_attributes":["Ask deck size (length x width) and mesh/hole spec","Ask the destoner make/model","Ask material and quantity"]},{"category":"Wire Mesh","item":"Flat & Round Wire Scourer Mesh","aliases":["scourer wire mesh"],"required_attributes":["Ask wire profile: flat or round","Ask mesh count/opening, wire gauge, and sheet size","Ask the scourer make/model and quantity"]},{"category":"Wire Mesh","item":"Mat Type Scourer Mesh","aliases":["scourer mat"],"required_attributes":["Ask mat size and mesh spec","Ask material and quantity"]},{"category":"Wire Mesh","item":"Pointed and Round Wire Scourer Mesh","aliases":[],"required_attributes":["Ask wire profile: pointed or round","Ask mesh count, sheet size, and quantity"]},{"category":"Perforated Sheet","item":"Checkboard Hole","aliases":["checkerboard perforation"],"required_attributes":["Confirm hole shape: round or square holes arranged in a checkerboard (offset) pattern","Ask hole size, sheet gauge, sheet size, material, quantity"]},{"category":"Perforated Sheet","item":"Dimple Shape","aliases":["raised dimple sheet","anti-slip dimple sheet"],"required_attributes":["Confirm with the client whether they mean a raised-dimple/anti-slip pattern or a plain punched hole -- the name is used loosely","Ask dimple/hole size, sheet gauge, sheet size, material, quantity"]},{"category":"Perforated Sheet","item":"Herring Bone Hole","aliases":["herringbone perforation"],"required_attributes":["Ask hole size, sheet gauge, sheet size, material, quantity"]},{"category":"Perforated Sheet","item":"Hexagonal Hole","aliases":["honeycomb perforation"],"required_attributes":["Ask hole size, sheet gauge, sheet size, material, quantity"]},{"category":"Perforated Sheet","item":"Indented Screen","aliases":["embossed screen"],"required_attributes":["Confirm the exact machine it is for, since this name is sometimes used loosely","Ask hole size, sheet gauge, sheet size, material, quantity"]},{"category":"Perforated Sheet","item":"Lip Shape","aliases":["louvre perforation","lip/louvre hole"],"required_attributes":["Confirm this is the pattern meant before quoting, as the name is sometimes used loosely","Ask hole size, sheet gauge, sheet size, material, quantity"]},{"category":"Perforated Sheet","item":"Oblong Slot Hole","aliases":["slotted hole sheet"],"required_attributes":["Ask slot size (length x width), sheet gauge, sheet size, material, quantity"]},{"category":"Perforated Sheet","item":"Round Hole","aliases":["round perforated sheet"],"required_attributes":["Ask hole diameter","Ask sheet gauge: 28 gauge (better quality) or 32 gauge (thinner/cheaper)","Ask sheet size, material, quantity"]},{"category":"Perforated Sheet","item":"Square Hole","aliases":[],"required_attributes":["Ask hole size, sheet gauge, sheet size, material, quantity"]},{"category":"Perforated Sheet","item":"Triangle Hole","aliases":[],"required_attributes":["Ask hole size, sheet gauge, sheet size, material, quantity"]},{"category":"Perforated Sheet","item":"Washer Whizzer Screen","aliases":["washer-whizzer wheat cleaning screen"],"required_attributes":["Ask the machine make/model first -- not a generic pattern","Ask cylinder/screen size and hole spec, material, quantity"]},{"category":"Miscellaneous","item":"Anti Vibration Mount","aliases":["AVM","vibration isolator mount","rubber shock mount"],"required_attributes":["Ask the load it needs to carry (kg) per mount, and the machine it is under","Ask stud/bolt size and mounting height","Ask quantity"]},{"category":"Miscellaneous","item":"Anti Vibration Rubber Pad","aliases":["vibration damping pad","isolation pad"],"required_attributes":["Ask size (length x width x thickness) and load per pad","Ask quantity"]},{"category":"Miscellaneous","item":"Bag Closer","aliases":["bag stitching machine","bag sewing machine"],"required_attributes":["Ask hand-operated or machine (powered) type, and the thread type used","Ask brand preference and quantity"]},{"category":"Miscellaneous","item":"Chakki Stone","aliases":["millstone","grinding stone","emery stone","chakki ka patthar"],"required_attributes":["Ask diameter and thickness","Ask whether it is the top or bottom stone -- traditional chakkis use a fixed bottom stone and a rotating top stone, and they are not always identical","Ask the chakki make/model","Ask quantity"]},{"category":"Miscellaneous","item":"Felt Sheet","aliases":["felt gasket sheet"],"required_attributes":["Ask size (length x width), thickness, and density/hardness if known","Ask quantity"]},{"category":"Miscellaneous","item":"Filter Cloth","aliases":["filtration fabric"],"required_attributes":["Ask micron rating/mesh, width, and material (polyester/PTFE/cotton)","Ask length required and quantity"]},{"category":"Miscellaneous","item":"Hammer Mill Beaters","aliases":["hammer mill hammers","swing hammers"],"required_attributes":["Ask beater size (length x width x thickness), material (MS, manganese steel, or SS), and mounting hole spacing","Ask the hammer mill make/model and quantity"]},{"category":"Miscellaneous","item":"Moisture Meter","aliases":["grain moisture tester","moisture analyzer"],"required_attributes":["Ask which grain/material it needs to test (wheat, maize, etc.) and the measurement range needed","Ask digital or analogue, and brand preference","Ask quantity"]},{"category":"Miscellaneous","item":"Rota Meter","aliases":["rotameter","variable area flowmeter"],"required_attributes":["Ask the fluid/air it is measuring and the flow range (LPM/CFM) needed","Ask pipe/line size and quantity"]},{"category":"Miscellaneous","item":"Test Sieves","aliases":["laboratory test sieves","ASTM/BSS test sieves","sieve shaker sieves"],"required_attributes":["Ask the mesh size(s)/aperture needed (in microns or mesh number)","Ask sieve diameter: standard 8 in/200 mm or 12 in/300 mm","Ask how many sieves, and whether a lid/pan/shaker is needed too","Ask quantity"]},{"category":"Miscellaneous","item":"Worm Hanger","aliases":["hanger bearing","screw conveyor hanger bearing"],"required_attributes":["Ask the shaft/worm size it supports and the machine make/model","Ask quantity"]}];
